public final class JadeTests {
    private JadeTests() {
    }

    public static void register(Map<String, TestCase> into) {
        into.put("formed_core_shows_its_part_count", new TestCase(20, JadeTests::formedCoreShowsItsPartCount));
        into.put("core_shows_its_problem_until_formed", new TestCase(20, JadeTests::coreShowsItsProblemUntilFormed));
        into.put("planter_shows_status_and_growing_seeds", new TestCase(20, JadeTests::planterShowsStatusAndGrowingSeeds));
        into.put("unformed_planter_shows_idle", new TestCase(20, JadeTests::unformedPlanterShowsIdle));
        into.put("empty_server_data_shows_no_lines", new TestCase(20, JadeTests::emptyServerDataShowsNoLines));
    }

    private static void formedCoreShowsItsPartCount(GameTestHelper helper) {
        Fixtures.Rig rig = Fixtures.rig(helper, 1);
        CoreBlockEntity core = helper.getBlockEntity(rig.core(), CoreBlockEntity.class);
        helper.startSequence()
                .thenWaitUntil(() -> helper.assertTrue(core.lastScan().formed(), "formed after the first scan"))
                .thenExecute(() -> helper.assertValueEqual(JadeInfo.coreLines(JadeInfo.core(core)),
